-- ADD-ONLY; preserve existing tables. Review remote schema before application.
CREATE TABLE IF NOT EXISTS memory_relations (id TEXT PRIMARY KEY, from_memory INTEGER NOT NULL, to_memory INTEGER NOT NULL, relation TEXT NOT NULL, source TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), valid_from INTEGER, valid_until INTEGER);
CREATE TABLE IF NOT EXISTS memory_conflicts (id TEXT PRIMARY KEY, memory_a INTEGER NOT NULL, memory_b INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', resolution TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_entities (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('PERSON','PROJECT','PLACE','ORGANIZATION','EVENT','DOCUMENT','TOPIC','DECISION','TASK')), name TEXT NOT NULL, source TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), valid_from INTEGER, valid_until INTEGER, metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS knowledge_relations (id TEXT PRIMARY KEY, subject TEXT NOT NULL, relation TEXT NOT NULL, object TEXT NOT NULL, source TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), valid_from INTEGER, valid_until INTEGER);
CREATE TABLE IF NOT EXISTS timeline_events (event_id TEXT PRIMARY KEY, type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, occurred_at INTEGER NOT NULL, source TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS model_providers (id TEXT PRIMARY KEY, name TEXT NOT NULL, adapter TEXT NOT NULL, secret_references TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS model_registry (id TEXT PRIMARY KEY, provider TEXT NOT NULL, model_id TEXT NOT NULL, capabilities TEXT NOT NULL DEFAULT '[]', context INTEGER, tools INTEGER NOT NULL DEFAULT 0, vision INTEGER NOT NULL DEFAULT 0, audio INTEGER NOT NULL DEFAULT 0, structured INTEGER NOT NULL DEFAULT 0, cost REAL, latency REAL, health TEXT NOT NULL DEFAULT 'UNKNOWN', enabled INTEGER NOT NULL DEFAULT 0, priority INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS model_stats (id TEXT PRIMARY KEY, model_id TEXT NOT NULL, request_id TEXT NOT NULL, duration_ms INTEGER, category TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS capabilities (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, version TEXT NOT NULL, provider TEXT NOT NULL, description TEXT NOT NULL, input_schema TEXT NOT NULL, output_schema TEXT NOT NULL, risk TEXT NOT NULL, permissions TEXT NOT NULL, health TEXT NOT NULL DEFAULT 'UNKNOWN', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS plugins (id TEXT PRIMARY KEY, active_version TEXT, status TEXT NOT NULL DEFAULT 'DISCOVERED', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS plugin_versions (id TEXT PRIMARY KEY, plugin_id TEXT NOT NULL, version TEXT NOT NULL, manifest TEXT NOT NULL, artifact_hash TEXT NOT NULL, proofs TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'DISCOVERED', created_at INTEGER NOT NULL, UNIQUE(plugin_id,version));
CREATE TABLE IF NOT EXISTS modules (id TEXT PRIMARY KEY, active_version TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS module_versions (id TEXT PRIMARY KEY, module_id TEXT NOT NULL, version TEXT NOT NULL, manifest TEXT NOT NULL, artifact_hash TEXT NOT NULL, proofs TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'DRAFT', created_at INTEGER NOT NULL, UNIQUE(module_id,version));
CREATE TABLE IF NOT EXISTS module_runs (id TEXT PRIMARY KEY, module_id TEXT NOT NULL, version TEXT NOT NULL, owner TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, result TEXT, error_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS module_lab_stages (run_id TEXT NOT NULL, stage TEXT NOT NULL, version TEXT NOT NULL, artifact_hash TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL, PRIMARY KEY(run_id,stage));
CREATE TABLE IF NOT EXISTS connectors (id TEXT PRIMARY KEY, provider TEXT NOT NULL, auth_type TEXT NOT NULL, capabilities TEXT NOT NULL DEFAULT '[]', secret_references TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'UNCONFIGURED', health TEXT NOT NULL DEFAULT 'UNKNOWN', metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS connector_states (connector_id TEXT PRIMARY KEY, sync_cursor TEXT, auth_verified_at INTEGER, last_error_code TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, capabilities TEXT NOT NULL DEFAULT '[]', permissions TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL, owner TEXT NOT NULL, plan TEXT NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automations (id TEXT PRIMARY KEY, owner TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('SCHEDULED','CONDITION','EVENT')), trigger TEXT NOT NULL, actions TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automation_runs (id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, cursor INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dev_changes (id TEXT PRIMARY KEY, base_commit TEXT NOT NULL, branch TEXT NOT NULL, status TEXT NOT NULL, plan TEXT NOT NULL, change_set TEXT NOT NULL DEFAULT '{}', tests TEXT NOT NULL DEFAULT '[]', candidate TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS memory_candidates (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, message_id TEXT NOT NULL, content TEXT NOT NULL, confidence REAL NOT NULL DEFAULT 0.5, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', created_at INTEGER NOT NULL, UNIQUE(message_id,content));
CREATE TABLE IF NOT EXISTS memories (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'episodic',content TEXT NOT NULL,importance REAL NOT NULL DEFAULT 0.5,confidence REAL NOT NULL DEFAULT 0.5,valid_from INTEGER,valid_until INTEGER,supersedes_id INTEGER,source TEXT NOT NULL DEFAULT 'chat',provenance TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}',fingerprint TEXT);
